import { z } from 'zod'

// Frozen copy of planner document schema v2, its export bundle and its change-proposal record, exactly as d325df4
// defined them. Two things must never follow the current schema:
// - the pre-upgrade copy: captured, hashed and downloaded as a version-2 artifact whatever the current schema is;
// - stored proposal records without a contract version: read as contract 1.0 history, never executed.
// Do not edit this file to follow the current model; add a new frozen module for a later version instead.

export const V2_SCHEMA_VERSION = 2 as const
const MINUTES_PER_DAY = 1440
const TOTAL_WEEK_HOURS = 168
const MAX_SOURCE_BYTES = 5 * 1024 * 1024

const id = z.string().min(1).max(64)
const text = (max: number) => z.string().trim().min(1).max(max)
const optionalText = (max: number) => z.string().max(max).optional()
const isoDate = z.iso.date()
const isoDateTime = z.iso.datetime({ offset: true })
const minute = z.number().int().min(0).max(MINUTES_PER_DAY - 1)
const dayIndex = z.number().int().min(0).max(6)
const colorKey = z.enum(['blue', 'green', 'orange', 'pink', 'purple', 'teal', 'yellow', 'red', 'gray'])
const goal = z.object({ type: z.enum(['max', 'min', 'none']), hoursPerWeek: z.number().min(0).max(TOTAL_WEEK_HOURS) })

const category = z.object({
  id, name: text(60), colorKey, customColor: z.string().regex(/^#[0-9a-fA-F]{6}$/).optional(), icon: optionalText(16), goal,
})
const blockFields = z.object({
  categoryId: id, title: text(120), notes: optionalText(500), days: z.array(dayIndex).min(1).max(7), start: minute, end: minute,
})
const timeBlock = z.object({ id, ...blockFields.shape })
  .refine((b) => b.start !== b.end, { message: 'block.zeroLength', path: ['end'] })
  .refine((b) => new Set(b.days).size === b.days.length, { message: 'block.duplicateDays', path: ['days'] })
const task = z.object({
  id, title: text(120), categoryId: id.optional(), durationMin: z.number().int().min(15).max(180), dueDate: isoDate.optional(),
  priority: z.union([z.literal(1), z.literal(2), z.literal(3)]), doneAt: isoDateTime.optional(), createdAt: isoDateTime,
})
const checkIn = z.object({
  date: isoDate, bedtime: minute.optional(), wake: minute.optional(), workEnd: minute.optional(),
  exercise: z.enum(['yes', 'no', 'not-planned']).optional(), stress: z.number().int().min(1).max(5).optional(), note: optionalText(280),
})
const blockActual = z.object({
  date: isoDate, blockId: id, categoryId: id, plannedStartAt: isoDateTime, plannedEndAt: isoDateTime,
  plannedMinutes: z.number().int().min(1).max(MINUTES_PER_DAY + 60), status: z.enum(['done', 'partial', 'skipped']),
  actualMinutes: z.number().int().min(0).max(MINUTES_PER_DAY + 60).optional(),
}).refine((a) => Math.round((Date.parse(a.plannedEndAt) - Date.parse(a.plannedStartAt)) / 60000) === a.plannedMinutes, { message: 'actual.plannedMinutesMismatch', path: ['plannedMinutes'] })
  .refine((a) => a.status !== 'partial' || (a.actualMinutes !== undefined && a.actualMinutes <= a.plannedMinutes), { message: 'actual.partialNeedsMinutes', path: ['actualMinutes'] })
const eventFields = z.object({
  title: text(120), start: isoDateTime, end: isoDateTime, allDay: z.boolean(), location: optionalText(200), notes: optionalText(2000),
  attendees: z.array(z.email()).max(50),
})
const plannerEvent = z.object({ id, ...eventFields.shape }).refine((e) => Date.parse(e.end) > Date.parse(e.start), { message: 'event.endBeforeStart', path: ['end'] })
const calendarSource = z.object({
  id, name: text(80), kind: z.enum(['file', 'url']), url: z.url({ protocol: /^(https?|webcal)$/ }).optional(), colorKey,
  lastSyncedAt: isoDateTime.optional(), lastError: optionalText(200),
})
const settings = z.object({
  locale: z.string().min(2).max(10), weekStartsOn: z.union([z.literal(0), z.literal(1)]), timeZone: z.string().min(1).max(64),
  onboardingDone: z.boolean(), theme: z.enum(['system', 'light', 'dark']),
})

export const plannerDocumentV2Schema = z.object({
  schemaVersion: z.literal(V2_SCHEMA_VERSION),
  workspaceId: id,
  revision: z.number().int().min(0),
  updatedAt: isoDateTime,
  settings,
  categories: z.array(category).max(100),
  blocks: z.array(timeBlock).max(1000),
  tasks: z.array(task).max(5000),
  checkIns: z.array(checkIn).max(3660),
  actuals: z.array(blockActual).max(50000),
  events: z.array(plannerEvent).max(5000),
  calendarSources: z.array(calendarSource).max(20),
  appliedProposalIds: z.array(id).max(200),
})
export type PlannerDocumentV2 = z.infer<typeof plannerDocumentV2Schema>

const exportBundleV2Schema = z.object({
  format: z.literal('next168-export'),
  bundleVersion: z.literal(1),
  exportedAt: isoDateTime,
  document: plannerDocumentV2Schema,
  calendarSourceTexts: z.record(z.string(), z.string().max(MAX_SOURCE_BYTES)),
})
export type ExportBundleV2 = z.infer<typeof exportBundleV2Schema>

function assertUnique(values: string[], field: string): void {
  if (new Set(values).size !== values.length) throw new Error(`document.duplicate:${field}`)
}

export function validateDocumentV2(raw: unknown): PlannerDocumentV2 {
  const doc = plannerDocumentV2Schema.parse(raw)
  new Intl.DateTimeFormat('en', { timeZone: doc.settings.timeZone }).format(0)
  for (const key of ['categories', 'blocks', 'tasks', 'events', 'calendarSources'] as const) {
    assertUnique(doc[key].map((item) => item.id), key)
  }
  assertUnique(doc.checkIns.map((item) => item.date), 'checkIns')
  assertUnique(doc.actuals.map((item) => JSON.stringify([item.blockId, Date.parse(item.plannedStartAt)])), 'actuals')
  assertUnique(doc.appliedProposalIds, 'appliedProposalIds')
  const categoryIds = new Set(doc.categories.map((item) => item.id))
  for (const item of [...doc.blocks, ...doc.tasks]) {
    if (item.categoryId !== undefined && !categoryIds.has(item.categoryId)) throw new Error('document.missingCategory')
  }
  for (const event of doc.events) {
    if (event.allDay && event.end.slice(0, 10) <= event.start.slice(0, 10)) throw new Error('document.allDayEventWithoutDates')
  }
  return doc
}

// `z.record` rebuilds the object and silently drops a `__proto__` key, so the texts are taken from the input's own entries.
function ownTexts(raw: unknown): Record<string, string> {
  const texts = (raw as { calendarSourceTexts?: unknown }).calendarSourceTexts as Record<string, unknown>
  return Object.fromEntries(Object.entries(texts).map(([key, value]) => {
    if (typeof value !== 'string' || value.length > MAX_SOURCE_BYTES) throw new Error('bundle.invalidSource')
    return [key, value]
  }))
}

export function validateBundleV2(raw: unknown): ExportBundleV2 {
  const bundle = exportBundleV2Schema.parse(raw)
  bundle.calendarSourceTexts = ownTexts(raw)
  bundle.document = validateDocumentV2(bundle.document)
  const sources = new Set(bundle.document.calendarSources.map((source) => source.id))
  for (const sourceId of sources) {
    if (!Object.prototype.hasOwnProperty.call(bundle.calendarSourceTexts, sourceId)) throw new Error('bundle.missingSource')
  }
  for (const [sourceId, value] of Object.entries(bundle.calendarSourceTexts)) {
    if (!sources.has(sourceId)) throw new Error('bundle.unknownSource')
    if (new TextEncoder().encode(value).length > MAX_SOURCE_BYTES) throw new Error('bundle.sourceTooLarge')
  }
  return bundle
}

// A stored version-2 document as d325df4 read it: the parsed document, or why it is not one.
export type StoredV2 = { kind: 'ok'; document: PlannerDocumentV2 } | { kind: 'not-v2' }

export function parseDocumentV2(json: string): StoredV2 {
  try {
    return { kind: 'ok', document: validateDocumentV2(JSON.parse(json)) }
  } catch {
    return { kind: 'not-v2' }
  }
}

// Contract 1.0 change proposals (history only: they are listed, never executed).
const newTaskFields = task.omit({ id: true, createdAt: true, doneAt: true })
export const legacyProposalOpSchema = z.discriminatedUnion('op', [
  z.object({ op: z.literal('add_category'), ref: id, category: z.object({ name: text(60), goal: goal.optional() }) }),
  z.object({ op: z.literal('add_block'), block: blockFields }),
  z.object({ op: z.literal('update_block'), id, patch: blockFields.partial() }),
  z.object({ op: z.literal('delete_block'), id }),
  z.object({ op: z.literal('add_task'), task: newTaskFields }),
  z.object({ op: z.literal('update_task'), id, patch: newTaskFields.partial() }),
  z.object({ op: z.literal('complete_task'), id }),
  z.object({ op: z.literal('add_event'), event: eventFields }),
  z.object({ op: z.literal('update_category_goal'), id, goal }),
])
export const legacyChangeProposalSchema = z.object({
  id,
  workspaceId: id,
  source: z.enum(['mcp', 'assistant', 'import']),
  clientName: optionalText(80),
  baseRevision: z.number().int().min(0),
  contentHash: z.string().min(16).max(128),
  summary: z.string().max(500),
  ops: z.array(legacyProposalOpSchema).min(1).max(200),
  status: z.enum(['pending', 'applied', 'rejected', 'stale']),
  createdAt: isoDateTime,
  decidedAt: isoDateTime.optional(),
  appliedRevision: z.number().int().min(0).optional(),
})
export type LegacyChangeProposal = z.infer<typeof legacyChangeProposalSchema>
